请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-125

=== 用户原始指令 (query.txt) ===
帮我做个比赛倒计时卡,数字要跳的那种,点一下进app,字要叠背景图上

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个比赛倒计时卡,数字要跳的那种,点一下进app,字要叠背景图上",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.calendar",
        "abilityName": "com.huawei.calendar.MainAbility",
        "uri": "calendar://event/sports-125"
      }
    }
  ],
  "dataModel": {
    "value": {
      "match": {
        "title": "申花 vs 海港",
        "countdownLabel": "距离开赛",
        "countdown": "09:36",
        "time": "今晚 19:35",
        "actionText": "进 App",
        "background": "assets/match-countdown-bg.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "match_countdown_background",
      "src": "assets/match-countdown-bg.png",
      "use": "sports countdown background",
      "description": "比赛倒计时背景图素材，用作整张卡片底图，适合承载叠加文字和赛前氛围。",
      "bindTo": "/match/background"
    }
  ]
}

